describe('Assign Category to Record', () => {
    beforeEach(() => {
        cy.visit('/records'); // Adjust the URL to the actual records page
    });

    it('should assign a category to a record successfully', () => {
        cy.get('.record-item').first().click(); // Click on the first record
        cy.get('.category-dropdown').select('Category 1'); // Select a category from the dropdown
        cy.get('.save-button').click(); // Click the save button
        cy.get('.notification').should('contain', 'Category assigned successfully'); // Verify success message
    });

    it('should show an error when no category is selected', () => {
        cy.get('.record-item').first().click(); // Click on the first record
        cy.get('.save-button').click(); // Click the save button without selecting a category
        cy.get('.error-message').should('contain', 'Please select a category'); // Verify error message
    });
});
